using Godot;
using System;
using Settings=Godot.Collections.Dictionary;
using GArray=Godot.Collections.Array;

public partial class TransformationWorkspaceOperations : RefCounted
{
    private static T Item<[MustBeVariant] T>(Control owner,string name) where T:GodotObject=>owner.Get(name).As<T>();
    private static RefCounted Session(Control owner)=>Item<RefCounted>(owner,"session");
    private static Resource Document(Control owner)=>Session(owner).Get("document").As<Resource>();
    private static Resource? Active(Control owner,Variant item=default)=>Session(owner).Call("active_state",item).As<Resource>();
    private static bool Flag(Control owner,string name)=>owner.Get(name).AsBool();
    private static void Pending(Control owner){owner.Set("_render_pending",true);owner.Set("_ui_pending",true);}
    public void changed(Control owner){Pending(owner);owner.EmitSignal("document_changed");}
    public void process(Control owner,double delta)
    {
        var edit=Item<Node>(owner,"edit_renderer");var animation=Item<Node>(owner,"animation_renderer");bool preview=Flag(owner,"previewing"),visible=owner.IsVisibleInTree();edit.Call("set_enabled",visible&&!preview);animation.Get("viewport").As<SubViewport>().RenderTargetUpdateMode=visible&&preview?SubViewport.UpdateMode.Always:SubViewport.UpdateMode.Disabled;if(!visible){owner.Set("playing",false);return;}var session=Session(owner);double duration=Document(owner).Get("duration").AsDouble();if(Flag(owner,"playing")){double time=session.Get("playhead").AsDouble()+delta;if(time>duration){if(Flag(owner,"loop"))time=Mathf.PosMod(time,duration);else{time=duration;owner.Set("playing",false);}}session.Set("playhead",time);owner.Set("_render_pending",true);}
        var canvas=Item<Control>(owner,"canvas");var timeline=Item<Control>(owner,"timeline");if(Flag(owner,"_render_pending")){owner.Set("_render_pending",false);if(preview){animation.Call("sync",session,session.Get("playhead"),new Settings());canvas.Set("preview",animation.Call("texture"));}else{if(!Flag(owner,"_gesture"))sync_edit_document(owner);if(Flag(owner,"_gesture")&&canvas.Get("_drag").AsString().StartsWith("resize",StringComparison.Ordinal))edit.Call("sync_transforms",owner.Get("edit_document"));else edit.Call("sync",owner.Get("edit_document"));canvas.Set("preview",edit.Call("texture"));}canvas.Set("previewing",preview);canvas.QueueRedraw();timeline.QueueRedraw();Item<Godot.Range>(owner,"time_control").SetValueNoSignal(session.Get("playhead").AsDouble());Item<Button>(owner,"play_button").Text=Flag(owner,"playing")?"Ⅱ":"▶";var state=Active(owner);Item<Label>(owner,"mode_label").Text=preview?"ANIMATION PREVIEW":state!=null?"EDIT STATE · "+state.Get("title").AsString():"EDIT STATE";if(preview){string status=animation.Get("status").AsString();Item<Label>(owner,"status").Text=status.Length>0?status:"Preview · state artwork is unchanged · Edit state to continue drawing";}}
        if(Flag(owner,"_ui_pending")&&!Flag(owner,"_gesture")&&!Flag(owner,"_number_drag")&&timeline.Get("drag").AsString().Length==0){owner.Set("_ui_pending",false);owner.Call("_refresh");}
    }
    public void sync_edit_document(Control owner)
    {
        var session=Session(owner);var document=new KiwiImageDocument();document.Set("canvas_size",Document(owner).Get("canvas_size"));foreach(var raw in Document(owner).Get("components").AsGodotArray()){var item=raw.As<Resource>();var state=Active(owner,item);if(state==null)continue;var art=state.Get("artwork").AsGodotObject().Call("copy_layer").As<Resource>();art.Set("label",item.Get("title"));art.Set("visible",art.Get("visible").AsBool()&&item.Get("visible").AsBool());art.Set("locked",item.Get("locked"));document.Get("layers").AsGodotArray().Add(art);}owner.Set("edit_document",document);var canvas=Item<Control>(owner,"canvas");canvas.Set("document",document);var selected=canvas.Get("selected").AsGodotArray();selected.Clear();foreach(var id in session.Get("selected").AsGodotArray())selected.Add(id);canvas.Set("preview_screen_space",false);var active=Active(owner);canvas.Set("pivot_uv",active!=null?active.Get("pivot"):Variant.From(new Vector2(.5f,.5f)));var reference=session.Get("pixel_reference").AsGodotDictionary();foreach(var pair in reference)document.Set(pair.Key.AsStringName(),pair.Value);var selection=canvas.Get("selection").As<Image>();var mask=session.Get("pixel_mask").As<Image>();if(selection!=mask){canvas.Set("selection",Variant.From(mask));canvas.Set("selection_texture",mask!=null?Variant.From(ImageTexture.CreateFromImage(mask)):default);}if(mask!=null&&reference.Count>0)canvas.Call("sync_pixel_selection");canvas.Set("onion",default(Variant));var primary=session.Call("primary").As<Resource>();if(Flag(owner,"onion")&&primary!=null){var states=primary.Get("states").AsGodotArray();int index=states.IndexOf(Variant.From(active));if(index>0)canvas.Set("onion",states[index-1].AsGodotObject().Get("artwork"));}
    }
    public void begin_gesture(Control owner){if(Flag(owner,"previewing"))return;var session=Session(owner);session.Call("begin");owner.Set("_gesture",true);var before=new Settings();owner.Set("_before_art",before);foreach(var id in Item<Control>(owner,"canvas").Get("selected").AsGodotArray()){var item=Document(owner).Call("component",id).As<Resource>();if(item!=null)before[id]=Active(owner,item)!.Get("artwork").AsGodotObject().Call("copy_layer");}}
    public void capture_art(Control owner){var canvas=Item<Control>(owner,"canvas");foreach(var id in canvas.Get("selected").AsGodotArray()){var item=Document(owner).Call("component",id).As<Resource>();var art=canvas.Get("document").AsGodotObject().Call("layer_for_id",id).As<Resource>();if(item==null||art==null||item.Get("locked").AsBool())continue;var state=Active(owner,item)!;bool visible=state.Get("artwork").AsGodotObject().Get("visible").AsBool();var copied=art.Call("copy_layer").As<Resource>();state.Set("artwork",copied);copied.Set("visible",visible);copied.Set("locked",false);}}
    public void preview_gesture(Control owner){capture_art(owner);Session(owner).Set("pixel_mask",Item<Control>(owner,"canvas").Get("selection"));owner.Set("_render_pending",true);}
    public void finish_gesture(Control owner){if(!Flag(owner,"_gesture"))return;capture_art(owner);var canvas=Item<Control>(owner,"canvas");var session=Session(owner);session.Set("pixel_mask",canvas.Get("selection"));foreach(string name in new[]{"pixel_selection","pixel_selection_owner","pixel_selection_reference","pixel_selection_reference_world"})session.Get("pixel_reference").AsGodotDictionary()[name]=canvas.Get("document").AsGodotObject().Get(name);touch_states(owner);owner.Set("_gesture",false);session.Call("commit","Edit component state");owner.Get("_before_art").AsGodotDictionary().Clear();}
    public void cancel_gesture(Control owner){owner.Set("_gesture",false);Session(owner).Call("cancel");owner.Get("_before_art").AsGodotDictionary().Clear();owner.Set("_render_pending",true);}
    public void touch_states(Control owner){foreach(var id in Session(owner).Get("selected").AsGodotArray()){var item=Document(owner).Call("component",id).As<Resource>();if(item!=null){var state=Active(owner,item)!;state.Set("revision",state.Get("revision").AsInt64()+1);}}}
    public void finish_pending(Control owner){var canvas=Item<Control>(owner,"canvas");canvas.Call("confirm_stroke");string drag=canvas.Get("_drag").AsString();if(drag.Length>0&&drag!="pan")canvas.Call("_finish",canvas.Get("_last"));if(Flag(owner,"_gesture"))finish_gesture(owner);}
    public void edit_mode(Control owner){owner.Set("playing",false);owner.Set("previewing",false);Item<Control>(owner,"canvas").Set("previewing",false);Pending(owner);}
    public void seek(Control owner,double value){finish_pending(owner);owner.Set("previewing",true);Item<Control>(owner,"canvas").Set("previewing",true);Session(owner).Set("playhead",Math.Clamp(value,0,Document(owner).Get("duration").AsDouble()));Pending(owner);}
    public void toggle_play(Control owner){finish_pending(owner);owner.Set("previewing",true);Item<Control>(owner,"canvas").Set("previewing",true);bool playing=!Flag(owner,"playing");owner.Set("playing",playing);var session=Session(owner);if(playing&&session.Get("playhead").AsDouble()>=Document(owner).Get("duration").AsDouble())session.Set("playhead",0.0);Pending(owner);}
    public Settings selected_key(Control owner){var selected=Session(owner).Get("selected_keys").AsGodotArray();foreach(var raw in Document(owner).Get("components").AsGodotArray()){var item=raw.As<Resource>();foreach(var keyRaw in item.Get("keys").AsGodotArray()){var key=keyRaw.As<Resource>();foreach(var id in selected)if(id.AsString()==key.Get("id").AsString())return new Settings {["component"]=item,["key"]=key};}}return new Settings();}
    public void key_selected(Control owner){owner.Set("playing",false);owner.Set("previewing",true);var selected=selected_key(owner);if(selected.Count>0)Session(owner).Set("playhead",selected["key"].AsGodotObject().Get("time"));Pending(owner);}
    public void edit_key_state(Control owner){var selected=selected_key(owner);if(selected.Count>0){var item=selected["component"].AsGodotObject();var chosen=Session(owner).Get("selected").AsGodotArray();chosen.Clear();chosen.Add(item.Get("id"));Session(owner).Get("edit_states").AsGodotDictionary()[item.Get("id")]=selected["key"].AsGodotObject().Get("state_id");}edit_mode(owner);}
}
